import { getRecord } from 'lightning/uiRecordApi';

const FIELDS = ['Account.Name', 'Account.Industry', 'Account.AnnualRevenue'];
const OPTIONAL_FIELDS = ['Account.Owner.Name'];

export default class AccountHeader extends LightningElement {
    @api recordId;

