import { LightningElement } from 'lwc';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import register from '@salesforce/apex/RegistrationController.register';

export default class EventRegistrationForm extends LightningElement {
    fullName = '';
    email = '';
    company = '';

    handleChange(event) {
        const field = event.target.dataset.field;
        this[field] = event.detail.value;
    }

    handleRegister() {
        // Step 1: Validate email domain before anything else
        const emailLwc = this.template.querySelector('lightning-input[data-field="email"]');
        const emailNativeInput = emailLwc.querySelector('input');

        const emailValue = this.email || '';
        const atIdx = emailValue.lastIndexOf('@');
        const domain = atIdx >= 0 ? emailValue.substring(atIdx + 1).toLowerCase() : '';
        const freeDomains = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'];

        if (freeDomains.includes(domain)) {
            emailNativeInput.setCustomValidity('Use your work email address.');
        } else {
            emailNativeInput.setCustomValidity('');
        }

        // Step 2: Call reportValidity on every input so all messages show at once
        const inputs = this.template.querySelectorAll('lightning-input');
        let allValid = true;
        inputs.forEach((lwcInput) => {
            const nativeInput = lwcInput.querySelector('input');
            nativeInput.reportValidity();
            if (!nativeInput.validity.valid) {
                allValid = false;
            }
        });

        // Step 3: If any input is invalid, stop
        if (!allValid) {
            return;
        }

        // Step 4: Call register imperatively
        register({ fullName: this.fullName, email: this.email, company: this.company })
            .then(() => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Registered',
                        variant: 'success'
                    })
                );
            })
            .catch((error) => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Registration failed',
                        message: error.body.message,
                        variant: 'error'
                    })
                );
            });
    }
}
